import java.util.*; 
public class PIEFLAVORED{
private static final long MOD = 998244353;
   public static void main(String[] args) 
   {
      Scanner sc = new Scanner(System.in);
      int totalN = sc.nextInt();
      long totalK = sc.nextLong();
      if(totalK >= totalN)
      {
         System.out.println("0");
      }
      else
      {
      int kVal = (int) totalK;
      int rVal = totalN - kVal;
      long[] combs = new long[rVal + 1];
      combs[0] = 1L;
      long num = 1L;
      long den = 1L;
      for(int i = 1; i <= rVal; i++)
      {
         num = (num * (rVal + 1 - i)) % MOD;
         den = (den * i) % MOD;
         combs[i] = (num * power(den, MOD - 2)) % MOD;
      }
      long result = 0;
      long flip = 1;
      for(int i = 0; i <= rVal; i++)
      {
         result += power((long)(rVal - i), (long)totalN) * flip * combs[i];
         result %= MOD;
         flip = -flip;
      }
      result = (result * choose((long)totalN, (long)kVal)) % MOD;
      if(kVal > 0)
      {
         result = (result * 2) % MOD;
      }
      if(result < 0)
      {
         result += MOD;
      }
      System.out.println("" + result);
      }
   }
public static long choose(long n, long k)  
    { 
      long numerator = 1;
      long denominator = 1;
      for(int i = (int)(n - k + 1); i <= n; i++)
      {
         numerator = (numerator * i) % MOD;
      } 
      for(int i = 1; i <= k; i++)
      {
         denominator = (denominator * i) % MOD;
      } 
      denominator = power(denominator, MOD - 2);
      return (numerator * denominator) % MOD;
    } 
public static long power(long base, long exp) 
{ 
    long res = 1;      
    base = base % MOD;
    while (exp > 0) 
    { 
        if ((exp & 1) == 1) 
        {    res = (res * base) % MOD;}
        exp >>= 1;  
        base = (base * base) % MOD; 
    } 
    return res; 
}
}
